/* =========================================================================
   UTILITIES — a deliberately small escape-hatch set. Reach for these to
   nudge spacing, alignment, and visibility without writing custom CSS.
   ========================================================================= */
@layer utilities {
  /* ---- Accessibility -------------------------------------------------- */
  .visually-hidden,
  .sr-only {
    position: absolute !important;
    inline-size: 1px; block-size: 1px;
    padding: 0; margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  /* Skip link: hidden until focused */
  .skip-link {
    position: absolute;
    inset-block-start: var(--sui-space-2);
    inset-inline-start: var(--sui-space-2);
    z-index: var(--sui-z-toast);
    padding: var(--sui-space-2) var(--sui-space-4);
    background-color: var(--sui-accent);
    color: var(--sui-text-on-accent);
    border-radius: var(--sui-radius);
    transform: translateY(-150%);
    transition: transform var(--sui-transition);
  }
  .skip-link:focus { transform: translateY(0); }

  /* ---- Text ----------------------------------------------------------- */
  .text-center  { text-align: center; }
  .text-start   { text-align: start; }
  .text-end     { text-align: end; }
  .text-balance { text-wrap: balance; }
  .text-muted   { color: var(--sui-text-muted); }
  .text-subtle  { color: var(--sui-text-subtle); }
  .text-accent  { color: var(--sui-accent); }
  .text-sm      { font-size: var(--sui-text-sm); }
  .text-lg      { font-size: var(--sui-text-lg); }
  .uppercase    { text-transform: uppercase; letter-spacing: var(--sui-tracking-wide); }
  .font-mono    { font-family: var(--sui-font-mono); }
  .font-bold    { font-weight: var(--sui-weight-bold); }
  .font-normal  { font-weight: var(--sui-weight-normal); }

  /* Truncate to one line */
  .truncate {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  /* Clamp to N lines via --lines */
  .line-clamp {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: var(--lines, 3);
    line-clamp: var(--lines, 3);
    overflow: hidden;
  }

  /* ---- Spacing (margin / padding shorthands) ------------------------- */
  .mt-0 { margin-block-start: 0; }
  .mt-2 { margin-block-start: var(--sui-space-2); }
  .mt-4 { margin-block-start: var(--sui-space-4); }
  .mt-6 { margin-block-start: var(--sui-space-6); }
  .mb-0 { margin-block-end: 0; }
  .mb-2 { margin-block-end: var(--sui-space-2); }
  .mb-4 { margin-block-end: var(--sui-space-4); }
  .mb-6 { margin-block-end: var(--sui-space-6); }
  .my-0 { margin-block: 0; }
  .mx-auto { margin-inline: auto; }
  .p-0 { padding: 0; }
  .p-4 { padding: var(--sui-space-4); }
  .p-6 { padding: var(--sui-space-6); }

  /* ---- Display & flow ------------------------------------------------- */
  .block        { display: block; }
  .inline-block { display: inline-block; }
  .hidden       { display: none !important; }
  .flex         { display: flex; }
  .inline-flex  { display: inline-flex; }
  .grid-cols-2  { display: grid; grid-template-columns: 1fr 1fr; gap: var(--sui-space-4); }
  .gap-2 { gap: var(--sui-space-2); }
  .gap-4 { gap: var(--sui-space-4); }
  .items-center  { align-items: center; }
  .justify-between { justify-content: space-between; }
  .flex-wrap { flex-wrap: wrap; }
  .grow { flex-grow: 1; }

  /* ---- Surfaces & shape ---------------------------------------------- */
  .surface  { background-color: var(--sui-surface); }
  .muted-bg { background-color: var(--sui-surface-alt); }
  .rounded  { border-radius: var(--sui-radius); }
  .rounded-full { border-radius: var(--sui-radius-full); }
  .border   { border: 1px solid var(--sui-border); }
  .shadow   { box-shadow: var(--sui-shadow); }
  .full-width { inline-size: 100%; }

  /* ---- Responsive visibility ----------------------------------------- */
  @media (max-width: 40rem) {
    .hide-mobile { display: none !important; }
  }
  @media (min-width: 40.0625rem) {
    .hide-desktop { display: none !important; }
  }

  /* Respect users who hide content from print */
  @media print {
    .no-print { display: none !important; }
  }
}

