1	/* =========================================================================
2	   BASE — classless styling for native semantic HTML.
3	   Write plain, correct HTML and it looks good with no classes at all.
4	   ========================================================================= */
5	@layer base {
6	  /* ---- Document ------------------------------------------------------- */
7	  html {
8	    font-family: var(--sui-font-sans);
9	    font-size: 100%;
10	    scroll-behavior: smooth;
11	  }
12	
13	  body {
14	    background-color: var(--sui-bg);
15	    color: var(--sui-text);
16	    font-size: var(--sui-text-base);
17	    transition: background-color var(--sui-transition), color var(--sui-transition);
18	  }
19	
20	  /* A bare <body> still reads well: gentle gutter + centered measure. */
21	  body > header,
22	  body > nav,
23	  body > main,
24	  body > footer,
25	  body > section,
26	  body > article {
27	    padding-inline: var(--sui-space-5);
28	  }
29	
30	  /* ---- Headings ------------------------------------------------------- */
31	  h1, h2, h3, h4, h5, h6 {
32	    line-height: var(--sui-leading-tight);
33	    font-weight: var(--sui-weight-bold);
34	    letter-spacing: var(--sui-tracking-tight);
35	    text-wrap: balance;
36	    color: var(--sui-text);
37	  }
38	
39	  h1 { font-size: var(--sui-text-3xl); }
40	  h2 { font-size: var(--sui-text-2xl); }
41	  h3 { font-size: var(--sui-text-xl); }
42	  h4 { font-size: var(--sui-text-lg); }
43	  h5 { font-size: var(--sui-text-base); font-weight: var(--sui-weight-semibold); }
44	  h6 {
45	    font-size: var(--sui-text-sm);
46	    font-weight: var(--sui-weight-semibold);
47	    text-transform: uppercase;
48	    letter-spacing: var(--sui-tracking-wide);
49	    color: var(--sui-text-muted);
50	  }
51	
52	  /* Vertical rhythm: space comes BEFORE block elements that follow content. */
53	  :is(h1, h2, h3, h4, h5, h6) + * { margin-block-start: var(--sui-space-3); }
54	  * + :is(h2, h3, h4, h5, h6)    { margin-block-start: var(--sui-space-6); }
55	
56	  /* ---- Text ----------------------------------------------------------- */
57	  p {
58	    max-width: var(--sui-measure);
59	  }
60	
61	  p + p,
62	  p + ul,
63	  p + ol,
64	  p + blockquote,
65	  p + pre,
66	  p + figure,
67	  p + table { margin-block-start: var(--sui-space-4); }
68	
69	  small { font-size: var(--sui-text-sm); color: var(--sui-text-muted); }
70	
71	  strong, b { font-weight: var(--sui-weight-semibold); }
72	  em, i, cite, dfn { font-style: italic; }
73	
74	  mark {
75	    background-color: var(--sui-mark-bg);
76	    color: inherit;
77	    padding-inline: 0.2em;
78	    border-radius: var(--sui-radius-sm);
79	  }
80	
81	  abbr[title] {
82	    text-decoration: underline dotted;
83	    text-underline-offset: 0.2em;
84	    cursor: help;
85	  }
86	
87	  del, s { color: var(--sui-text-muted); }
88	  ins { text-decoration: underline; text-decoration-color: var(--sui-success); }
89	
90	  sub, sup { font-size: 0.75em; line-height: 0; }
91	
92	  kbd {
93	    font-family: var(--sui-font-mono);
94	    font-size: 0.85em;
95	    background-color: var(--sui-surface);
96	    color: var(--sui-text);
97	    border: 1px solid var(--sui-border-strong);
98	    border-bottom-width: 2px;
99	    border-radius: var(--sui-radius-sm);
100	    padding: 0.1em 0.4em;
101	    box-shadow: var(--sui-shadow-sm);
102	  }
103	
104	  /* ---- Links ---------------------------------------------------------- */
105	  a {
106	    color: var(--sui-accent);
107	    text-decoration: underline;
108	    text-decoration-thickness: 1px;
109	    text-underline-offset: 0.18em;
110	    text-decoration-color: color-mix(in srgb, var(--sui-accent) 40%, transparent);
111	    transition: color var(--sui-transition), text-decoration-color var(--sui-transition);
112	  }
113	
114	  a:hover {
115	    color: var(--sui-accent-hover);
116	    text-decoration-color: currentColor;
117	  }
118	
119	  /* ---- Lists ---------------------------------------------------------- */
120	  ul, ol {
121	    padding-inline-start: var(--sui-space-5);
122	  }
123	
124	  li { margin-block-start: var(--sui-space-1); }
125	  li::marker { color: var(--sui-text-muted); }
126	
127	  /* Nested lists tuck in tighter */
128	  li > :is(ul, ol) { margin-block-start: var(--sui-space-1); }
129	
130	  dl { display: grid; grid-template-columns: auto 1fr; gap: var(--sui-space-2) var(--sui-space-4); }
131	  dt { font-weight: var(--sui-weight-semibold); }
132	  dd { color: var(--sui-text-muted); margin: 0; }
133	
134	  /* ---- Quotes --------------------------------------------------------- */
135	  blockquote {
136	    border-inline-start: 3px solid var(--sui-accent);
137	    padding: var(--sui-space-1) var(--sui-space-5);
138	    color: var(--sui-text-muted);
139	    font-size: var(--sui-text-lg);
140	    font-style: italic;
141	  }
142	
143	  blockquote cite {
144	    display: block;
145	    margin-block-start: var(--sui-space-2);
146	    font-size: var(--sui-text-sm);
147	    font-style: normal;
148	    color: var(--sui-text-subtle);
149	  }
150	
151	  blockquote cite::before { content: "— "; }
152	
153	  q { quotes: "“" "”" "‘" "’"; }
154	
155	  /* ---- Code ----------------------------------------------------------- */
156	  code, kbd, samp, pre {
157	    font-family: var(--sui-font-mono);
158	    font-size: 0.9em;
159	  }
160	
161	  :not(pre) > code, samp {
162	    background-color: var(--sui-code-bg);
163	    color: var(--sui-code-text);
164	    padding: 0.15em 0.4em;
165	    border-radius: var(--sui-radius-sm);
166	    white-space: nowrap;
167	  }
168	
169	  pre {
170	    background-color: var(--sui-code-bg);
171	    color: var(--sui-code-text);
172	    padding: var(--sui-space-4);
173	    border-radius: var(--sui-radius);
174	    border: 1px solid var(--sui-border);
175	    overflow-x: auto;
176	    line-height: var(--sui-leading-snug);
177	    tab-size: 2;
178	  }
179	
180	  pre code {
181	    background: none;
182	    padding: 0;
183	    white-space: pre;
184	    font-size: inherit;
185	  }
186	
187	  /* ---- Media ---------------------------------------------------------- */
188	  img, video {
189	    height: auto;
190	    border-radius: var(--sui-radius);
191	  }
192	
193	  figure {
194	    display: flex;
195	    flex-direction: column;
196	    gap: var(--sui-space-2);
197	  }
198	
199	  figcaption {
200	    font-size: var(--sui-text-sm);
201	    color: var(--sui-text-muted);
202	    text-align: center;
203	  }
204	
205	  /* ---- Rules & separators -------------------------------------------- */
206	  hr {
207	    border: none;
208	    border-block-start: 1px solid var(--sui-border);
209	    margin-block: var(--sui-space-6);
210	  }
211	
212	  /* ---- Tables --------------------------------------------------------- */
213	  table {
214	    width: 100%;
215	    border-collapse: collapse;
216	    font-size: var(--sui-text-sm);
217	    text-align: start;
218	  }
219	
220	  caption {
221	    caption-side: bottom;
222	    padding-block-start: var(--sui-space-3);
223	    font-size: var(--sui-text-sm);
224	    color: var(--sui-text-muted);
225	    text-align: start;
226	  }
227	
228	  th, td {
229	    padding: var(--sui-space-3) var(--sui-space-4);
230	    border-block-end: 1px solid var(--sui-border);
231	    vertical-align: top;
232	  }
233	
234	  thead th {
235	    text-align: start;
236	    font-weight: var(--sui-weight-semibold);
237	    color: var(--sui-text-muted);
238	    border-block-end: 2px solid var(--sui-border-strong);
239	    white-space: nowrap;
240	  }
241	
242	  tbody tr {
243	    transition: background-color var(--sui-transition);
244	  }
245	  tbody tr:hover {
246	    background-color: var(--sui-surface-alt);
247	  }
248	
249	  tfoot {
250	    font-weight: var(--sui-weight-semibold);
251	  }
252	
253	  /* ---- Disclosure: <details>/<summary> ------------------------------- */
254	  details {
255	    background-color: var(--sui-surface);
256	    border: 1px solid var(--sui-border);
257	    border-radius: var(--sui-radius);
258	    padding: var(--sui-space-3) var(--sui-space-4);
259	  }
260	
261	  details + details { margin-block-start: var(--sui-space-2); }
262	
263	  summary {
264	    cursor: pointer;
265	    font-weight: var(--sui-weight-semibold);
266	    list-style: none;
267	    display: flex;
268	    align-items: center;
269	    gap: var(--sui-space-2);
270	  }
271	
272	  summary::-webkit-details-marker { display: none; }
273	
274	  summary::before {
275	    content: "";
276	    width: 0.5em;
277	    height: 0.5em;
278	    border-right: 2px solid var(--sui-text-muted);
279	    border-bottom: 2px solid var(--sui-text-muted);
280	    transform: rotate(-45deg);
281	    transition: transform var(--sui-transition);
282	  }
283	
284	  details[open] > summary::before { transform: rotate(45deg); }
285	
286	  details[open] > summary { margin-block-end: var(--sui-space-3); }
287	
288	  /* ---- Dialog --------------------------------------------------------- */
289	  dialog {
290	    background-color: var(--sui-surface);
291	    color: var(--sui-text);
292	    border: 1px solid var(--sui-border);
293	    border-radius: var(--sui-radius-lg);
294	    box-shadow: var(--sui-shadow-lg);
295	    padding: var(--sui-space-6);
296	    max-width: min(90vw, var(--sui-container-sm));
297	  }
298	
299	  dialog::backdrop {
300	    background-color: rgb(15 23 42 / 0.45);
301	    backdrop-filter: blur(2px);
302	  }
303	
304	  /* ---- Progress & meter ---------------------------------------------- */
305	  progress, meter {
306	    inline-size: 100%;
307	    block-size: 0.6rem;
308	    border: none;
309	    border-radius: var(--sui-radius-full);
310	    overflow: hidden;
311	    background-color: var(--sui-surface-alt);
312	  }
313	  progress::-webkit-progress-bar { background-color: var(--sui-surface-alt); }
314	  progress::-webkit-progress-value { background-color: var(--sui-accent); }
315	  progress::-moz-progress-bar { background-color: var(--sui-accent); }
316	
317	  /* ---- Focus visibility (global) ------------------------------------- */
318	  :focus-visible {
319	    outline: 2px solid var(--sui-accent);
320	    outline-offset: 2px;
321	    border-radius: var(--sui-radius-sm);
322	  }
323	  :focus:not(:focus-visible) { outline: none; }
324	
325	  /* ---- Selection ------------------------------------------------------ */
326	  ::selection {
327	    background-color: var(--sui-accent-soft);
328	    color: var(--sui-text);
329	  }
330	
331	  /* ---- Scrollbars (subtle) ------------------------------------------- */
332	  * {
333	    scrollbar-width: thin;
334	    scrollbar-color: var(--sui-border-strong) transparent;
335	  }
336	}
337

