1	/* =========================================================================
2	   FORMS — classless styling for native form controls.
3	   ========================================================================= */
4	@layer base {
5	  fieldset {
6	    border: 1px solid var(--sui-border);
7	    border-radius: var(--sui-radius);
8	    padding: var(--sui-space-4) var(--sui-space-5);
9	  }
10	
11	  legend {
12	    padding-inline: var(--sui-space-2);
13	    font-weight: var(--sui-weight-semibold);
14	    color: var(--sui-text);
15	  }
16	
17	  label {
18	    display: inline-block;
19	    font-size: var(--sui-text-sm);
20	    font-weight: var(--sui-weight-medium);
21	    margin-block-end: var(--sui-space-1);
22	  }
23	
24	  /* Stack label + control + help text inside a <p> or <div> wrapper */
25	  form p,
26	  form > div {
27	    margin-block-start: var(--sui-space-4);
28	  }
29	
30	  /* ---- Text-like inputs ---------------------------------------------- */
31	  input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]):not([type="submit"]):not([type="reset"]):not([type="button"]),
32	  textarea,
33	  select {
34	    display: block;
35	    inline-size: 100%;
36	    padding: var(--sui-space-2) var(--sui-space-3);
37	    font-size: var(--sui-text-base);
38	    color: var(--sui-text);
39	    background-color: var(--sui-surface);
40	    border: 1px solid var(--sui-border-strong);
41	    border-radius: var(--sui-radius);
42	    transition: border-color var(--sui-transition), box-shadow var(--sui-transition);
43	    appearance: none;
44	  }
45	
46	  input::placeholder,
47	  textarea::placeholder {
48	    color: var(--sui-text-subtle);
49	  }
50	
51	  input:focus-visible,
52	  textarea:focus-visible,
53	  select:focus-visible {
54	    outline: none;
55	    border-color: var(--sui-accent);
56	    box-shadow: 0 0 0 3px var(--sui-focus-ring);
57	  }
58	
59	  textarea {
60	    min-block-size: 6rem;
61	    resize: vertical;
62	    line-height: var(--sui-leading-snug);
63	  }
64	
65	  /* Native select arrow */
66	  select:not([multiple]) {
67	    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="none" stroke="%2364748b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>');
68	    background-repeat: no-repeat;
69	    background-position: right var(--sui-space-3) center;
70	    padding-inline-end: var(--sui-space-6);
71	  }
72	
73	  /* ---- Checkbox & radio ---------------------------------------------- */
74	  input[type="checkbox"],
75	  input[type="radio"] {
76	    appearance: none;
77	    inline-size: 1.15em;
78	    block-size: 1.15em;
79	    margin-inline-end: var(--sui-space-1);
80	    vertical-align: -0.18em;
81	    border: 1px solid var(--sui-border-strong);
82	    background-color: var(--sui-surface);
83	    cursor: pointer;
84	    transition: background-color var(--sui-transition), border-color var(--sui-transition);
85	  }
86	  input[type="checkbox"] { border-radius: var(--sui-radius-sm); }
87	  input[type="radio"]    { border-radius: var(--sui-radius-full); }
88	
89	  input[type="checkbox"]:checked,
90	  input[type="radio"]:checked {
91	    background-color: var(--sui-accent);
