156	  .badge[data-variant="warning"] { background-color: color-mix(in srgb, var(--sui-warning) 18%, transparent); color: var(--sui-amber-500); }
157	  .badge[data-variant="danger"]  { background-color: color-mix(in srgb, var(--sui-danger) 14%, transparent); color: var(--sui-danger); }
