/* =========================================================================
   FEEDBACK & STATUS — opt-in components for transient and ambient messaging.
   Toasts, banners, empty states, progress bars, and a page loading bar.
   Use these when native HTML has no element for the pattern; everything
   themes through --sui-* tokens and respects reduced-motion preferences.
   ========================================================================= */
@layer components {
  /* ---- Toast notifications ------------------------------------------- */
  /* `.toast-region` is the fixed, click-through stack; each `.toast` is a
     card that re-enables pointer events. Default pins to the bottom-end. */
  .toast-region {
    position: fixed;
    inset-block-end: var(--sui-space-5);
    inset-inline-end: var(--sui-space-5);
    z-index: var(--sui-z-toast);
    display: flex;
    flex-direction: column;
    gap: var(--sui-space-3);
    inline-size: min(24rem, calc(100vw - 2 * var(--sui-space-5)));
    max-block-size: calc(100vh - 2 * var(--sui-space-5));
    overflow: hidden;
    pointer-events: none;
  }

  /* Position variants — `*-end` reverses stack order so new toasts (appended
     to the DOM) appear nearest the anchored edge. */
  .toast-region[data-position="top-end"] {
    inset-block: var(--sui-space-5) auto;
    inset-inline: auto var(--sui-space-5);
  }
  .toast-region[data-position="top-center"] {
    inset-block: var(--sui-space-5) auto;
    inset-inline: 0;
    margin-inline: auto;
    align-items: center;
  }
  .toast-region[data-position="bottom-end"] {
    inset-block: auto var(--sui-space-5);
    inset-inline: auto var(--sui-space-5);
    flex-direction: column-reverse;
  }

  .toast {
    display: flex;
    align-items: flex-start;
    gap: var(--sui-space-3);
    padding: var(--sui-space-4);
    background-color: var(--sui-surface);
    color: var(--sui-text);
    border: 1px solid var(--sui-border);
    border-inline-start: 4px solid var(--sui-text-muted);
    border-radius: var(--sui-radius);
    box-shadow: var(--sui-shadow-md);
    pointer-events: auto;
