  /* ---- Print ----------------------------------------------------------
     Ink-friendly output: force the light palette even under dark mode
     (OS preference or [data-theme="dark"]), drop shadows/transitions/
     animation, hide chrome that means nothing on paper, and keep cards/
     tables/quotes from splitting across a page break. */
  @media print {
    .no-print { display: none !important; }

    /* Re-declaring these tokens here wins over the dark-theme rules in
       tokens.css regardless of selector specificity, because @layer order
       (utilities > tokens) decides the cascade, not specificity. */
    :root,
    :root[data-theme="dark"] {
      --sui-bg:            #ffffff;
      --sui-surface:       #ffffff;
      --sui-surface-alt:   var(--sui-gray-100);
      --sui-border:        var(--sui-gray-200);
      --sui-border-strong: var(--sui-gray-300);
      --sui-text:          var(--sui-gray-900);
      --sui-text-muted:    var(--sui-gray-500);
      --sui-text-subtle:   var(--sui-gray-400);
      --sui-code-bg:       var(--sui-gray-100);
      --sui-code-text:     var(--sui-gray-800);
      --sui-mark-bg:       #fef08a;
    }

    *, *::before, *::after {
      box-shadow: none !important;
      text-shadow: none !important;
      transition: none !important;
      animation: none !important;
      backdrop-filter: none !important;
    }

    /* Interactive-only chrome: nothing to click on paper. */
    nav,
    .toast-region,
    .skip-link,
    dialog,
    .menu,
    .popover-card,
    .drawer,
    [role="tablist"],
    button,
    input[type="button"],
    input[type="submit"],
    input[type="reset"] {
      display: none !important;
    }

    /* Don't let a block split across a page break. */
    .card,
    table,
    blockquote {
      break-inside: avoid;
      page-break-inside: avoid;
    }
  }
}

