(() => {
  const sheet = [...document.styleSheets].find(s => s.href && s.href.includes('semantica.css'));
  if (!sheet) return 'NO_SHEET';
  const results = [];
  function walk(rules, path) {
    for (const r of rules) {
      if (r instanceof CSSMediaRule) {
        if (/forced-colors|print/.test(r.conditionText || r.media.mediaText)) {
          results.push({media: r.media.mediaText, ruleCount: r.cssRules.length, selectors: [...r.cssRules].map(x => x.selectorText || x.cssText.slice(0,40))});
